{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/sitemap-footer.json
    A footer with the brand, a tagline, groups of links and the copyright. Axes: layout (columns: brand above, equal columns per group, row: the brand, the group names and the copyright in one row), signup mode (none, first: a sign-up above the links), status mode (none, show: a live status pill), density. The live status itself is a port contract.
    Props (p): label, brand, tagline, copyright, groups, signup, status, id, layout, density, landmarkLabel. *}
{var $v_label = ($p['label'] ?? null)}
{var $v_brand = ($p['brand'] ?? null)}
{var $v_tagline = ($p['tagline'] ?? null)}
{var $v_copyright = ($p['copyright'] ?? null)}
{var $v_groups = ($p['groups'] ?? null)}
{var $v_signup = ($p['signup'] ?? null)}
{var $v_status = ($p['status'] ?? null)}
{var $v_id = ($p['id'] ?? 'footer')}
{var $v_layout = ($p['layout'] ?? 'columns')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{if ui_t(ui_eq($v_layout, 'card'))}
  {=ui_include('blocks/footer-card.latte', ['p' => ['label' => $v_label, 'brand' => $v_brand, 'groups' => $v_groups, 'landmarkLabel' => $v_landmarkLabel]])|noescape}
{else}
  {capture $c_21}
    {capture $c_20}
      {if ui_t(ui_eq(ui_get($v_signup, ['mode']), 'first'))}
        {capture $c_6}
          {capture $c_1}
            {=ui_text(ui_get($v_signup, ['title']))}
          {/capture}
          {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'xl', 'Weight' => 'bold'], 'children' => $c_1])|noescape}
          {capture $c_5}
            {capture $c_2}
              {=ui_text(ui_get($v_signup, ['label']))}
            {/capture}
            {=ui_include('ui/label/label.latte', ['p' => ['HTMLFor' => ui_s(ui_tpl('{0}-email', [$v_id])), 'Class' => 'sr-only'], 'children' => $c_2])|noescape}
            {capture $c_4}
              {=ui_include('ui/input/input.latte', ['p' => ['Type' => 'email', 'Name' => 'email', 'Class' => 'min-w-0 flex-1', 'Attrs' => ui_attrs(['id', ui_tpl('{0}-email', [$v_id]), 'data-testid', 'field'])]])|noescape}
              {capture $c_3}
                {=ui_text(ui_get($v_signup, ['submit']))}
              {/capture}
              {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'default', 'Size' => 'default', 'Type' => 'submit', 'Attrs' => ui_attrs(['data-testid', 'submit'])], 'children' => $c_3])|noescape}
            {/capture}
            {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'start', 'Class' => 'w-full flex-wrap'], 'children' => $c_4])|noescape}
          {/capture}
          {=ui_include('ui/form/form.latte', ['p' => ['Method' => 'dialog', 'Class' => ui_s(ui_cnv(['w-full max-w-md', (ui_t(false) ? 'mx-auto' : '')])), 'Attrs' => ui_attrs(['data-testid', 'email-form'])], 'children' => $c_5])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Class' => 'max-w-md', 'Attrs' => ui_attrs(['data-testid', 'signup'])], 'children' => $c_6])|noescape}
      {/if}
      {if ui_t(ui_eq($v_layout, 'columns'))}
        {capture $c_11}
          {capture $c_9}
            {capture $c_7}
              {=ui_text($v_brand)}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xl', 'Weight' => 'bold'], 'children' => $c_7])|noescape}
            {capture $c_8}
              {=ui_text($v_tagline)}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_8])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Class' => 'md:w-64 md:shrink-0'], 'children' => $c_9])|noescape}
          {capture $c_10}
            {=ui_include('blocks/footer-columns.latte', ['p' => ['label' => $v_label, 'groups' => $v_groups, 'landmarkLabel' => $v_landmarkLabel]])|noescape}
          {/capture}
          {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'min-w-0 flex-1'], 'children' => $c_10])|noescape}
        {/capture}
        {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex flex-col gap-8 md:flex-row md:items-start md:gap-12', 'Attrs' => ui_attrs(['data-slot', 'footer-top'])], 'children' => $c_11])|noescape}
      {else}
        {capture $c_16}
          {capture $c_12}
            {=ui_text($v_brand)}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'base', 'Weight' => 'bold'], 'children' => $c_12])|noescape}
          {capture $c_15}
            {capture $c_14}
              {foreach ui_l($v_groups) as $v_g}
                {capture $c_13}
                  {=ui_text(ui_get($v_g, ['title']))}
                {/capture}
                {=ui_include('ui/link/link.latte', ['p' => ['Href' => '#/', 'Variant' => 'default', 'Class' => 'text-sm', 'Attrs' => ui_attrs(['data-testid', 'group'])], 'children' => $c_13])|noescape}
              {/foreach}
            {/capture}
            {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Class' => 'flex-wrap'], 'children' => $c_14])|noescape}
          {/capture}
          {=ui_include('blocks/nav-block.latte', ['p' => ['label' => (ui_t($v_landmarkLabel) ? ui_uniq(ui_tpl('{0}, {1}', [$v_label, $v_landmarkLabel])) : $v_label)], 'children' => $c_15])|noescape}
        {/capture}
        {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '6', 'Align' => 'center', 'Justify' => 'between', 'Class' => 'flex-wrap'], 'children' => $c_16])|noescape}
      {/if}
      {capture $c_19}
        {capture $c_17}
          {=ui_text($v_copyright)}
        {/capture}
        {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_17])|noescape}
        {if ui_t(ui_eq(ui_get($v_status, ['mode']), 'show'))}
          {capture $c_18}
            {=ui_text(ui_get($v_status, ['label']))}
          {/capture}
          {=ui_include('blocks/pill.latte', ['p' => ['tone' => 'green', 'icon' => 'circle-check'], 'children' => $c_18])|noescape}
        {/if}
      {/capture}
      {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'center', 'Justify' => 'between', 'Class' => 'flex-wrap border-t border-border pt-6'], 'children' => $c_19])|noescape}
    {/capture}
    {=ui_include('ui/container/container.latte', ['p' => ['Class' => ui_s(ui_cnv(['mx-auto w-full max-w-6xl px-4', 'flex flex-col gap-8', (ui_t(ui_eq($v_density, 'compact')) ? 'py-6' : 'py-12')])), 'Attrs' => ui_attrs(['data-slot', 'container'])], 'children' => $c_20])|noescape}
  {/capture}
  {=ui_include('ui/block/block.latte', ['p' => ['Tag' => 'footer', 'Class' => 'mt-12 border-t border-border', 'Attrs' => ui_attrs(['data-testid', 'site-footer', 'data-layout', $v_layout, 'aria-label', $v_landmarkLabel])], 'children' => $c_21])|noescape}
{/if}
